def ev(key, label):
    e = LOG[(key, label)]
    pub, title, stype, lim = SOURCES[(key, label)]
    return {
        'evidence_id': f'{key}/{label}', 'url': e['url'], 'final_url': e.get('final_url'),
        'publisher': pub, 'title': title, 'source_type': stype, 'accessed_at': e['accessed_at'],
        'access_status': e['access_status'], 'local_evidence_path': e.get('text_path'),
        'local_raw_path': e.get('raw_path'), 'sha256': e.get('sha256'), 'limitations': lim,
    }


def failed_attempts(key):
    return [{'url': e['url'], 'label': e['label'], 'accessed_at': e['accessed_at'], 'access_status': e['access_status'],
             'error': e.get('error') or f"HTTP {e.get('status')} 본문 {e.get('text_chars')}자"}
            for (k, _), e in LOG.items() if k == key and e['access_status'] != 'body_read_http_200']


def C(cid, ctype, claim, verdict, *refs):
    """refs: (label, quote) 쌍. quote 는 저장 본문의 정확한 부분 문자열."""
    return {'claim_id': cid, 'type': ctype, 'claim': claim, 'verdict': verdict,
            'evidence': [{'evidence_id': lab, 'quote': q} for lab, q in refs]}


